sys_script_client.script:
/**
 * Sync Filter -- onChange of class_mapping.
 *
 * Keeps cmdb_condition_table in step with the chosen Class Mapping WITHOUT a save.
 *
 * Not optional, and not a duplicate of the "Populate Sync Filter Condition Table" business
 * rule. The condition builder for cmdb_condition reads the dependent field's value off the
 * form, not the database, so without this it keeps offering the previous Class Mapping's table
 * until the record is saved and reloaded -- and the author writes a condition against the
 * wrong table in the meantime.
 *
 * getReference is used rather than a GlideAjax because source_table is a plain field on the
 * referenced record; there is nothing to compute server-side.
 */
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return;
    }

    if (newValue === '') {
        g_form.setValue('cmdb_condition', '');
        g_form.setValue('cmdb_condition_table', '');
        return;
    }

    g_form.getReference('class_mapping', function(classMapping) {
        var sourceTable = classMapping ? classMapping.source_table : '';

        // Same Class Mapping, or a different one over the same table: whatever condition is
        // already there is still valid, so leave it alone.
        if (g_form.getValue('cmdb_condition_table') === sourceTable) {
            return;
        }

        // Clear the condition BEFORE the table. A condition authored against the old table
        // cannot be rendered against the new one, and the builder would be left showing rows
        // for columns the new table may not have.
        g_form.setValue('cmdb_condition', '');
        g_form.setValue('cmdb_condition_table', sourceTable);
    });
}
